  private enqueue(command: BridgeCommand): void {
    const waiter = this.waiters.shift();
    if (waiter === undefined) {
      this.queue.push(command);
      return;
    }
    const entry = this.pending.get(command.id);
    if (entry !== undefined) {
      entry.deliveredAt = Date.now();
    }
    waiter(command);
  }

  /** 分清三种超时：扩展没轮询 / 取走了没回 / 正常但慢。 */
  private timeoutMessage(timeoutMs: number): string {
    const pollAgeMs = this.lastSeenAt === undefined ? undefined : Date.now() - this.lastSeenAt;
    const entries = [...this.pending.values()];
    const delivered = entries.some((entry) => entry.deliveredAt !== undefined);
    if (delivered) {
      return `Chrome 命令超时（${timeoutMs}ms）：扩展收到了命令但没回结果`;
    }
    if (pollAgeMs === undefined || pollAgeMs > 60_000) {
      return `Chrome 命令超时（${timeoutMs}ms）：Chrome 扩展没有在轮询（${
        pollAgeMs === undefined ? "从未见过" : `${Math.round(pollAgeMs / 1000)}s 前`
      }）。确认 Chrome 开着，且 chrome://extensions 里加载了 Pi Chrome Connector`;
    }
    return `Chrome 命令超时（${timeoutMs}ms）：扩展在轮询但没及时取走命令`;
  }

  /** 扩展来取命令。取不到就空转等到超时（长轮询）。 */
  private takeCommand(timeoutMs: number): Promise<BridgeCommand | undefined> {
    const queued = this.queue.shift();
    if (queued !== undefined) {
      const entry = this.pending.get(queued.id);
      if (entry !== undefined) {
        entry.deliveredAt = Date.now();
      }
      return Promise.resolve(queued);
    }
    return new Promise<BridgeCommand | undefined>((resolve) => {
      let settled = false;
      const waiter = (command: BridgeCommand | undefined): void => {
        if (settled) {
          return;
        }
        settled = true;
        clearTimeout(timer);
        this.waiters = this.waiters.filter((entry) => entry !== waiter);
        resolve(command);
      };
      const timer = setTimeout(() => {
        waiter(undefined);
      }, timeoutMs);
      this.waiters.push(waiter);
    });
  }

  /** HTTP 入口：四个端点。语义与 pi-chrome 自带的桥一致。 */
  private async handle(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const origin = request.headers.get("origin") ?? "";
    const secFetchSite = request.headers.get("sec-fetch-site") ?? "";
    // 有 Origin 就必须是扩展自己；没有 Origin 才看 sec-fetch-site（本地进程直连）。
    const fromExtension =
      origin !== ""
        ? origin.startsWith("chrome-extension://")
        : secFetchSite === "" || secFetchSite === "none" || secFetchSite === "same-origin";

    if (request.method === "OPTIONS") {
      if (!fromExtension) {
        return json(403, { ok: false, error: "browser origin not allowed" });
      }
      return new Response(null, { status: 204, headers: corsHeaders(origin) });
    }

    if (request.method === "GET" && url.pathname === "/status") {
      return json(200, await this.status());
    }

    if (request.method === "GET" && url.pathname === "/next") {
      if (!fromExtension) {
        return json(403, { ok: false, error: "browser origin not allowed" });
      }
      this.lastSeenAt = Date.now();
      this.clientName = url.searchParams.get("name") ?? this.clientName;
      const command = await this.takeCommand(this.pollTimeoutMs);
      return json(200, command === undefined ? { type: "none" } : { type: "command", command }, corsHeaders(origin));
    }

    if (request.method === "POST" && url.pathname === "/result") {
      const body = (await request.json().catch(() => ({}))) as BridgeResult;
      const entry = this.pending.get(body.id);
      if (entry === undefined) {
        return json(404, { ok: false, error: "unknown command id" }, corsHeaders(origin));
      }
      clearTimeout(entry.timer);
      this.pending.delete(body.id);
      if (body.ok) {
        entry.resolve(body.result);
      } else {
        entry.reject(new Error(body.error ?? "Chrome 命令失败"));
      }
      return json(200, { ok: true }, corsHeaders(origin));
    }

    if (request.method === "POST" && url.pathname === "/command") {
      // 只接受本地进程（没有浏览器 origin 头）
      if (origin !== "" || secFetchSite !== "") {
        return json(403, { ok: false, error: "Chrome commands are accepted only from local processes" });
      }
      const body = (await request.json().catch(() => ({}))) as {
        action?: string;
        params?: Record<string, unknown>;
        timeoutMs?: number;
      };
      if (body.action === undefined || body.action === "") {
        return json(400, { ok: false, error: "Missing command action" });
      }
      try {
        const result = await this.dispatch(body.action, body.params ?? {}, body.timeoutMs ?? DEFAULT_COMMAND_TIMEOUT_MS);
        return json(200, { ok: true, result });
      } catch (error) {
        return json(504, { ok: false, error: (error as Error).message });
      }
    }

    return json(404, { error: "not found" });
  }

  /** 释放端口。owner 模式下停掉 server，client 模式下什么都不做。 */
  async stop(): Promise<void> {
    for (const entry of this.pending.values()) {
      clearTimeout(entry.timer);
      entry.reject(new Error("Chrome 桥已关闭"));
    }
    this.pending.clear();
    this.queue.length = 0;
    for (const waiter of this.waiters) {
      waiter(undefined);
    }
    this.waiters.length = 0;
    if (this.server !== undefined) {
      await this.server.stop(true);
      this.server = undefined;
    }
    this.mode = undefined;
  }
}

/** JSON 响应。 */
function json(status: number, body: unknown, extraHeaders: Record<string, string> = {}): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...extraHeaders },
  });
}

/** 扩展是浏览器源（chrome-extension://），要回 CORS 头。 */
function corsHeaders(origin: string): Record<string, string> {
  if (!origin.startsWith("chrome-extension://")) {
    return {};
  }
  return {
    "access-control-allow-origin": origin,
    "access-control-allow-methods": "GET,POST,OPTIONS",
    "access-control-allow-headers": "content-type",
    "access-control-expose-headers": "x-pi-chrome-version",
    vary: "origin",
  };
}

/** 端口被占用：Bun 抛 EADDRINUSE，Node 风格的错误信息也认。 */
function isAddrInUse(error: unknown): boolean {
  const code = (error as { code?: string }).code ?? "";
  const message = (error as Error).message ?? "";
  return code === "EADDRINUSE" || /EADDRINUSE|address already in use/i.test(message);
}

}

/**
 * 抓取并写 `runs/<date>/twitter_raw.txt`。
 *
 * 失败不抛：Twitter 只是四个来源之一，挂了不影响其它三个出稿。
 */
export async function fetchTwitterRaw(options: {
  dataDir: string;
  date: string;
  bridge?: ChromeBridge;
  minTweets?: number;
}): Promise<TwitterRawResult> {
  const bridge = options.bridge ?? (await ChromeBridge.connect());
  const ownsBridge = options.bridge === undefined;
  try {
    await ensureExtensionConnected(bridge);
    await checkExtensionVersion(bridge);

    const tweets = await fetchTwitterTimeline({
      bridge,
      ...(options.minTweets === undefined ? {} : { minTweets: options.minTweets }),
    });
    const raw = renderTwitterRaw(tweets);

    const dir = join(options.dataDir, "runs", options.date);
    await mkdir(dir, { recursive: true });
    await writeFile(join(dir, "twitter_raw.txt"), raw, "utf8");

    return { ok: true, count: tweets.length, role: bridge.role };
  } catch (error) {
    return { ok: false, count: 0, error: (error as Error).message };
  } finally {
    if (ownsBridge) {
      await bridge.stop();
    }
  }
}

/**
 * 确保 Chrome 扩展在轮询。
 *
 * Chrome 没开就拉起来（扩展在 Chrome 里，不开就没人轮询），最多等 45s。
 * Chrome 已经开着却连不上扩展 → 不重复拉起（`open -a` 会把 Chrome 拉到前台，
 * 07:00 抢用户屏幕），直接报错让人去 chrome://extensions 看。
 */
export async function ensureExtensionConnected(bridge: ChromeBridge, waitMs = 45_000): Promise<void> {
  const status = await bridge.status();
  if (status.connected) {
    return;
  }
  if (!isChromeRunning()) {
    launchChrome();
  }
  const deadline = Date.now() + waitMs;
  while (Date.now() < deadline) {
    await sleep(500);
    const current = await bridge.status();
    if (current.connected) {
      return;
    }
  }
  throw new Error(
    "Chrome 扩展没有连上：确认 Chrome 在运行，且 chrome://extensions 里加载了 Pi Chrome Connector",
  );
}

/** Chrome 在跑吗。用来决定要不要拉起它。 */
export function isChromeRunning(): boolean {
  const result = spawnSync("pgrep", ["-x", "Google Chrome"], { stdio: "ignore" });
  return result.status === 0;
}

/**
 * 扩展版本下限检查。
 *
 * 协议变了的话（老扩展不认识新动作），表现是「命令超时」或「Unknown action」，
 * 不如在这里直接说清楚。
 */
export async function checkExtensionVersion(bridge: ChromeBridge): Promise<string> {
  const info = (await bridge.send("tab.version", {}, 15_000)) as { extensionVersion?: string } | undefined;
  const version = info?.extensionVersion ?? "";
  if (version === "") {
    return "";
  }
  if (isOlderThan(version, MIN_EXTENSION_VERSION)) {
    throw new Error(`Chrome 扩展版本过旧（${version} < ${MIN_EXTENSION_VERSION}）：到 chrome://extensions 重新加载 Pi Chrome Connector`);
  }
  return version;
}

/** 拉起 Chrome（默认 profile，扩展就装在里面）。 */
function launchChrome(): void {
  spawnSync("open", ["-a", "Google Chrome"], { stdio: "ignore" });
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

/** 语义化版本比较：`a` 是否比 `b` 老。 */
function isOlderThan(a: string, b: string): boolean {
  const parse = (value: string): number[] =>
    value
      .split(".")
      .map((part) => Number.parseInt(part, 10))
      .map((part) => (Number.isFinite(part) ? part : 0));
  const left = parse(a);
  const right = parse(b);
  for (let i = 0; i < Math.max(left.length, right.length); i += 1) {
    const l = left[i] ?? 0;
    const r = right[i] ?? 0;
    if (l !== r) {
      return l < r;
    }
  }
  return false;
}

